    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 76-year-old patient is recovering from a total hip arthroplasty. According to current guidelines for patients at standard risk for deep vein thrombosis (DVT), what is the most appropriate duration for pharmacologic VTE prophylaxis?', '["At least 10 to 14 days, up to 35 days", "3 months", "6 months", "3 to 5 days", "24 to 48 hours"]'::jsonb, 0, 'Current orthopedic guidelines recommend extending pharmacologic venous thromboembolism (VTE) prophylaxis for a minimum of 10 to 14 days, and up to 35 days, following major joint replacement surgery (THA or TKA) to minimize the risk of DVT and pulmonary embolism.'),
    (v_topic_id, 'A 65-year-old patient complains of a ''limp'' 6 weeks after a primary total hip arthroplasty. On examination, the operative leg appears longer. What is a common intraoperative cause for lengthening the operative leg during THA?', '["Maximizing soft tissue tension to prevent dislocation", "Aggressive reaming of the acetabulum", "Placing the femoral component in varus", "Excessive resection of the femoral neck", "Using a smaller femoral head size"]'::jsonb, 0, 'Leg length discrepancy is a common patient complaint after THA. Surgeons sometimes intentionally or unintentionally lengthen the leg to increase myofascial tension (especially of the abductors) to improve hip stability and decrease the risk of dislocation.'),
    (v_topic_id, 'A 76-year-old patient is undergoing a total joint arthroplasty. The surgical team is reviewing the risk of perioperative systemic complications. Regarding wound dehiscence, which of the following is most accurate in this setting?', '["It is a rare complication seen almost exclusively in young patients", "It is completely preventable with prophylactic antibiotics", "It is solely caused by the type of implant bearing surface used", "Associated with early excessive flexion or poor nutrition", "It only occurs after the 3-month postoperative mark"]'::jsonb, 3, 'Wound dehiscence is a known systemic complication following major joint arthroplasty. Specifically, it is associated with early excessive flexion or poor nutrition. Proper medical optimization and perioperative care are crucial for risk mitigation.'),
    (v_topic_id, 'A 89-year-old sustains a fall and suffers a periprosthetic femur fracture around their total hip arthroplasty. Radiographs show the fracture is Around the stem, stem is loose. This is classified as Vancouver B2. What is the most appropriate management?', '["Nonoperative management with protected weight-bearing", "Revision arthroplasty with proximal femoral replacement", "ORIF with intramedullary nailing", "ORIF with plates and cables", "Revision arthroplasty with a longer stem"]'::jsonb, 4, 'The Vancouver classification dictates treatment of postoperative periprosthetic femur fractures. Vancouver B2 fractures occur Around the stem, stem is loose and are best managed by Revision arthroplasty with a longer stem.'),
    (v_topic_id, 'A 85-year-old patient is recovering from a total hip arthroplasty. According to current guidelines for patients at standard risk for deep vein thrombosis (DVT), what is the most appropriate duration for pharmacologic VTE prophylaxis?', '["24 to 48 hours", "At least 10 to 14 days, up to 35 days", "6 months", "3 to 5 days", "3 months"]'::jsonb, 1, 'Current orthopedic guidelines recommend extending pharmacologic venous thromboembolism (VTE) prophylaxis for a minimum of 10 to 14 days, and up to 35 days, following major joint replacement surgery (THA or TKA) to minimize the risk of DVT and pulmonary embolism.'),
    (v_topic_id, 'A 73-year-old patient presents 6 months after a posterior-stabilized total knee arthroplasty complaining of a painful catch or ''clunk'' when extending the knee from a flexed position. What is the most likely etiology of this symptom?', '["Polyethylene wear of the patellar button", "Aseptic loosening of the tibial component", "Fibrous nodule formation at the superior pole of the patella", "Infection with Staphylococcus epidermidis", "Rupture of the patellar tendon"]'::jsonb, 2, 'Patellar clunk syndrome occurs in some posterior-stabilized TKAs when a fibrous nodule forms at the superior pole of the patella. As the knee extends, this nodule catches in the intercondylar box of the femoral component and then pops out with a painful ''''clunk''''.'),
    (v_topic_id, 'A 61-year-old patient presents 6 months after a posterior-stabilized total knee arthroplasty complaining of a painful catch or ''clunk'' when extending the knee from a flexed position. What is the most likely etiology of this symptom?', '["Aseptic loosening of the tibial component", "Polyethylene wear of the patellar button", "Rupture of the patellar tendon", "Fibrous nodule formation at the superior pole of the patella", "Infection with Staphylococcus epidermidis"]'::jsonb, 3, 'Patellar clunk syndrome occurs in some posterior-stabilized TKAs when a fibrous nodule forms at the superior pole of the patella. As the knee extends, this nodule catches in the intercondylar box of the femoral component and then pops out with a painful ''''clunk''''.'),
    (v_topic_id, 'A 79-year-old patient presents with a painful left hip and a palpable soft-tissue mass. They underwent a metal-on-metal total hip arthroplasty 10 years ago. Serum cobalt and chromium levels are elevated. What is the most likely diagnosis?', '["Heterotopic ossification", "Periprosthetic joint infection", "Iliopsoas bursitis", "Adverse local tissue reaction (ALTR) / Pseudotumor", "Aseptic loosening due to polyethylene wear"]'::jsonb, 3, 'Metal-on-metal hip implants can produce metal ion wear debris, which can trigger an adverse local tissue reaction (ALTR), often manifesting as a solid or cystic pseudotumor, pain, and elevated serum metal ions.'),
    (v_topic_id, 'A 88-year-old sustains a fall and suffers a periprosthetic femur fracture around their total hip arthroplasty. Radiographs show the fracture is Well below the stem tip. This is classified as Vancouver C. What is the most appropriate management?', '["Nonoperative management with protected weight-bearing", "Revision arthroplasty with proximal femoral replacement", "ORIF with plates and cables", "Revision arthroplasty with a longer stem", "ORIF with plate fixation"]'::jsonb, 4, 'The Vancouver classification dictates treatment of postoperative periprosthetic femur fractures. Vancouver C fractures occur Well below the stem tip and are best managed by ORIF with plate fixation.'),
    (v_topic_id, 'A 73-year-old patient is undergoing a total joint arthroplasty. The surgical team is reviewing the risk of perioperative systemic complications. Regarding urinary tract infection, which of the following is most accurate in this setting?', '["It only occurs after the 3-month postoperative mark", "It is completely preventable with prophylactic antibiotics", "It is a rare complication seen almost exclusively in young patients", "It is solely caused by the type of implant bearing surface used", "Associated with prolonged indwelling catheterization"]'::jsonb, 4, 'Urinary tract infection is a known systemic complication following major joint arthroplasty. Specifically, it is associated with prolonged indwelling catheterization. Proper medical optimization and perioperative care are crucial for risk mitigation.'),
    (v_topic_id, 'A 61-year-old patient presents with a painful left hip and a palpable soft-tissue mass. They underwent a metal-on-metal total hip arthroplasty 10 years ago. Serum cobalt and chromium levels are elevated. What is the most likely diagnosis?', '["Iliopsoas bursitis", "Heterotopic ossification", "Aseptic loosening due to polyethylene wear", "Adverse local tissue reaction (ALTR) / Pseudotumor", "Periprosthetic joint infection"]'::jsonb, 3, 'Metal-on-metal hip implants can produce metal ion wear debris, which can trigger an adverse local tissue reaction (ALTR), often manifesting as a solid or cystic pseudotumor, pain, and elevated serum metal ions.'),
    (v_topic_id, 'A 74-year-old patient is undergoing a total joint arthroplasty. The surgical team is reviewing the risk of perioperative systemic complications. Regarding wound dehiscence, which of the following is most accurate in this setting?', '["Associated with early excessive flexion or poor nutrition", "It is a rare complication seen almost exclusively in young patients", "It is solely caused by the type of implant bearing surface used", "It is completely preventable with prophylactic antibiotics", "It only occurs after the 3-month postoperative mark"]'::jsonb, 0, 'Wound dehiscence is a known systemic complication following major joint arthroplasty. Specifically, it is associated with early excessive flexion or poor nutrition. Proper medical optimization and perioperative care are crucial for risk mitigation.'),
    (v_topic_id, 'A 60-year-old patient complains of a ''limp'' 6 weeks after a primary total hip arthroplasty. On examination, the operative leg appears longer. What is a common intraoperative cause for lengthening the operative leg during THA?', '["Using a smaller femoral head size", "Placing the femoral component in varus", "Excessive resection of the femoral neck", "Maximizing soft tissue tension to prevent dislocation", "Aggressive reaming of the acetabulum"]'::jsonb, 3, 'Leg length discrepancy is a common patient complaint after THA. Surgeons sometimes intentionally or unintentionally lengthen the leg to increase myofascial tension (especially of the abductors) to improve hip stability and decrease the risk of dislocation.'),
    (v_topic_id, 'A 61-year-old patient is 8 weeks out from a primary total knee arthroplasty and complains of severe stiffness. Range of motion is 10 to 70 degrees. After failing aggressive physical therapy, what is the next most appropriate step in management?', '["Open arthrolysis and synovectomy", "Manipulation under anesthesia (MUA)", "Arthroscopic lysis of adhesions", "Revision total knee arthroplasty", "Long-term casting in extension"]'::jsonb, 1, 'Stiffness or arthrofibrosis after TKA is a frustrating complication. If aggressive physical therapy fails, the most appropriate next step within the first 2-3 months is typically a manipulation under anesthesia (MUA) to break up intra-articular adhesions and improve range of motion.'),
    (v_topic_id, 'A 82-year-old patient presents with increasing pain in the knee 3 weeks after a total knee arthroplasty. Aspiration yields purulent fluid. What is the most likely responsible organism and the standard surgical management?', '["Cutibacterium acnes; One-stage exchange arthroplasty", "Streptococcus pyogenes; Suppressive intravenous antibiotics only", "Staphylococcus epidermidis; Debridement, antibiotics, and implant retention (DAIR)", "Staphylococcus aureus; Debridement, antibiotics, and implant retention (DAIR)", "Staphylococcus aureus; Two-stage exchange arthroplasty"]'::jsonb, 3, 'Periprosthetic joint infections present differently based on timing. Acute infections (typically < 3-4 weeks) are often caused by highly virulent organisms like Staphylococcus aureus and can sometimes be managed with Debridement, antibiotics, and implant retention (DAIR). Chronic infections are usually due to less virulent organisms like Staph epidermidis and require a two-stage exchange.'),
    (v_topic_id, 'A 70-year-old patient complains of a ''limp'' 6 weeks after a primary total hip arthroplasty. On examination, the operative leg appears longer. What is a common intraoperative cause for lengthening the operative leg during THA?', '["Placing the femoral component in varus", "Maximizing soft tissue tension to prevent dislocation", "Aggressive reaming of the acetabulum", "Using a smaller femoral head size", "Excessive resection of the femoral neck"]'::jsonb, 1, 'Leg length discrepancy is a common patient complaint after THA. Surgeons sometimes intentionally or unintentionally lengthen the leg to increase myofascial tension (especially of the abductors) to improve hip stability and decrease the risk of dislocation.'),
    (v_topic_id, 'A 77-year-old patient presents with a painful right hip and a palpable soft-tissue mass. They underwent a metal-on-metal total hip arthroplasty 10 years ago. Serum cobalt and chromium levels are elevated. What is the most likely diagnosis?', '["Adverse local tissue reaction (ALTR) / Pseudotumor", "Aseptic loosening due to polyethylene wear", "Heterotopic ossification", "Periprosthetic joint infection", "Iliopsoas bursitis"]'::jsonb, 0, 'Metal-on-metal hip implants can produce metal ion wear debris, which can trigger an adverse local tissue reaction (ALTR), often manifesting as a solid or cystic pseudotumor, pain, and elevated serum metal ions.'),
    (v_topic_id, 'A 72-year-old patient is undergoing a total joint arthroplasty. The surgical team is reviewing the risk of perioperative systemic complications. Regarding urinary tract infection, which of the following is most accurate in this setting?', '["Associated with prolonged indwelling catheterization", "It is solely caused by the type of implant bearing surface used", "It is a rare complication seen almost exclusively in young patients", "It only occurs after the 3-month postoperative mark", "It is completely preventable with prophylactic antibiotics"]'::jsonb, 0, 'Urinary tract infection is a known systemic complication following major joint arthroplasty. Specifically, it is associated with prolonged indwelling catheterization. Proper medical optimization and perioperative care are crucial for risk mitigation.'),
    (v_topic_id, 'A 90-year-old sustains a fall and suffers a periprosthetic femur fracture around their total hip arthroplasty. Radiographs show the fracture is Around the stem, stem is well-fixed. This is classified as Vancouver B1. What is the most appropriate management?', '["ORIF with intramedullary nailing", "ORIF with plates and cables", "Revision arthroplasty with proximal femoral replacement", "Revision arthroplasty with a longer stem", "Nonoperative management with protected weight-bearing"]'::jsonb, 1, 'The Vancouver classification dictates treatment of postoperative periprosthetic femur fractures. Vancouver B1 fractures occur Around the stem, stem is well-fixed and are best managed by ORIF with plates and cables.'),
    (v_topic_id, 'A 72-year-old sustains a fall and suffers a periprosthetic femur fracture around their total hip arthroplasty. Radiographs show the fracture is Trochanteric region. This is classified as Vancouver A. What is the most appropriate management?', '["ORIF with plates and cables", "Revision arthroplasty with proximal femoral replacement", "Nonoperative or cerclage wires if widely displaced", "Revision arthroplasty with a longer stem", "Nonoperative management with protected weight-bearing"]'::jsonb, 2, 'The Vancouver classification dictates treatment of postoperative periprosthetic femur fractures. Vancouver A fractures occur Trochanteric region and are best managed by Nonoperative or cerclage wires if widely displaced.'),
    (v_topic_id, 'A 56-year-old patient presents with vague, progressive shoulder pain 1 year after an anatomic total shoulder arthroplasty. Inflammatory markers are minimally elevated, and there is no frank purulence on aspiration. Intraoperative cultures eventually grow a slow-growing anaerobic Gram-positive bacillus. Which organism is most likely responsible?', '["Pseudomonas aeruginosa", "Streptococcus pyogenes", "Staphylococcus epidermidis", "Cutibacterium acnes", "Staphylococcus aureus"]'::jsonb, 3, 'Cutibacterium (formerly Propionibacterium) acnes is a common skin flora around the shoulder and a frequent cause of indolent, chronic periprosthetic joint infections following shoulder arthroplasty. It often requires prolonged incubation (up to 14 days) to grow in culture.'),
    (v_topic_id, 'A 68-year-old patient presents with increasing pain in the shoulder 3 weeks after a total shoulder arthroplasty. Aspiration yields purulent fluid. What is the most likely responsible organism and the standard surgical management?', '["Staphylococcus aureus; Debridement, antibiotics, and implant retention (DAIR)", "Staphylococcus epidermidis; Debridement, antibiotics, and implant retention (DAIR)", "Staphylococcus aureus; Two-stage exchange arthroplasty", "Streptococcus pyogenes; Suppressive intravenous antibiotics only", "Cutibacterium acnes; One-stage exchange arthroplasty"]'::jsonb, 0, 'Periprosthetic joint infections present differently based on timing. Acute infections (typically < 3-4 weeks) are often caused by highly virulent organisms like Staphylococcus aureus and can sometimes be managed with Debridement, antibiotics, and implant retention (DAIR). Chronic infections are usually due to less virulent organisms like Staph epidermidis and require a two-stage exchange.'),
    (v_topic_id, 'A 67-year-old patient undergoes a total hip arthroplasty via an anterior approach. Postoperatively, the patient has profound weakness in knee extension and decreased sensation over the anterior thigh. Which structure was most likely injured during the procedure?', '["Femoral nerve", "Sciatic nerve", "Obturator nerve", "Lateral femoral cutaneous nerve", "Superior gluteal nerve"]'::jsonb, 0, 'The femoral nerve provides motor innervation to the quadriceps (knee extension) and sensory innervation to the anterior thigh. It can be injured during an anterior approach to the hip due to retractor placement over the anterior rim of the acetabulum.'),
    (v_topic_id, 'A 78-year-old patient complains of a ''limp'' 6 weeks after a primary total hip arthroplasty. On examination, the operative leg appears longer. What is a common intraoperative cause for lengthening the operative leg during THA?', '["Placing the femoral component in varus", "Using a smaller femoral head size", "Aggressive reaming of the acetabulum", "Maximizing soft tissue tension to prevent dislocation", "Excessive resection of the femoral neck"]'::jsonb, 3, 'Leg length discrepancy is a common patient complaint after THA. Surgeons sometimes intentionally or unintentionally lengthen the leg to increase myofascial tension (especially of the abductors) to improve hip stability and decrease the risk of dislocation.'),
    (v_topic_id, 'A 78-year-old sustains a fall and suffers a periprosthetic femur fracture around their total hip arthroplasty. Radiographs show the fracture is Trochanteric region. This is classified as Vancouver A. What is the most appropriate management?', '["Nonoperative or cerclage wires if widely displaced", "ORIF with plates and cables", "Nonoperative management with protected weight-bearing", "Revision arthroplasty with proximal femoral replacement", "Revision arthroplasty with a longer stem"]'::jsonb, 0, 'The Vancouver classification dictates treatment of postoperative periprosthetic femur fractures. Vancouver A fractures occur Trochanteric region and are best managed by Nonoperative or cerclage wires if widely displaced.'),
    (v_topic_id, 'A 76-year-old patient presents with severe shoulder pain and limited range of motion. Imaging and clinical evaluation confirm isolated humeral head osteonecrosis with preserved glenoid cartilage. Which of the following is the most appropriate surgical intervention?', '["Reverse Total Shoulder Arthroplasty (rTSA)", "Arthroscopic debridement and subacromial decompression", "Hemiarthroplasty", "Arthrodesis", "Anatomic Total Shoulder Arthroplasty (TSA)"]'::jsonb, 2, 'The primary indication for Hemiarthroplasty is isolated humeral head osteonecrosis with preserved glenoid cartilage. Anatomic TSA relies on an intact rotator cuff to maintain the humeral head centered on the glenoid. In contrast, rTSA is designed for cuffs that are severely deficient, utilizing the deltoid muscle to substitute for the rotator cuff.'),
    (v_topic_id, 'A 75-year-old patient complains of a ''limp'' 6 weeks after a primary total hip arthroplasty. On examination, the operative leg appears longer. What is a common intraoperative cause for lengthening the operative leg during THA?', '["Using a smaller femoral head size", "Maximizing soft tissue tension to prevent dislocation", "Placing the femoral component in varus", "Excessive resection of the femoral neck", "Aggressive reaming of the acetabulum"]'::jsonb, 1, 'Leg length discrepancy is a common patient complaint after THA. Surgeons sometimes intentionally or unintentionally lengthen the leg to increase myofascial tension (especially of the abductors) to improve hip stability and decrease the risk of dislocation.'),
